import React from 'react';
import {useSRSession, useSRStateAPI, type MessageComponentProps} from '@sr/sdk';
function Cover() {
  const session = useSRSession();
  const state = useSRStateAPI();
  const [busy, setBusy] = React.useState(false);
  const [error, setError] = React.useState('');
  async function startEncounter() {
    if (busy) return;
    setBusy(true); setError('');
    try { await session.send('[仪式:初遇]'); }
    catch { setError('发送失败，请检查会话设置。'); }
    finally { setBusy(false); }
  }
  async function startNight() {
    if (busy) return;
    setBusy(true); setError('');
    try {
      const results = await state.batchUpdateState([
        {path: '进度.阶段', value: '夜晚'},
        {path: '灵力', value: 3}
      ]);
      if (results.every(result => result.success)) await session.send('[仪式:夜晚]');
      else setError('部分状态更新失败。');
    } catch { setError('发送失败，请检查会话设置。'); } finally { setBusy(false); }
  }
  return <section style={{display:"grid", gap:"12px", minWidth:"180px"}}><h2>测试开局</h2><p>选择故事开始的时刻。</p><div style={{display:"flex", gap:"8px"}}><button disabled={busy} onClick={startEncounter}>初遇</button><button disabled={busy} onClick={startNight}>夜晚</button></div>{error && <p role="alert">{error}</p>}</section>;
}
function Choice({namedGroups}: MessageComponentProps) { return <span>{namedGroups.text}</span>; }
Choice.srDisplay = 'inline';
export default {Cover, Choice};
